UPDATE `EMAIL_SCENARIO` SET `SUBJECT`='{{inviteClient.loginUsername}} @{{inviteClient.vendorOrgName}} invites you to join SourceLead a Global Talent Harvesting Platform', `BODY`='Dear {{inviteClient.FirstName}} {{inviteClient.LastName}},\n\n{{inviteClient.loginUsername}} @{{inviteClient.vendorOrgName}} is using SourceLead a Global Talent Harvesting Platform to Manage Human\nResource for their company.\n\nThis email is being sent to you because {{inviteClient.loginUsername}} @{{inviteClient.vendorOrgName}} is using SourceLead to Manage their\nresource including but not limited to Project management,Applicaiton Tracking,Time Tracking,Billing,\nCrowd Sourcing etc.
\nSourceLead makes it easy for teams to work more efficiently by Managing the Resource. Over 8,000 remote\nteams uses it daily.\n\nPlease find your user id and temporary password below to login to the sourcelead platform and setup your\norganization.\nUsername : {{inviteClient.userName}}\nPassword  : {{inviteClient.Password}}\n{{inviteClient.acceptURL}}\n\nNeed Support?\nWe have video tutorials, live chat, and a great support site to help if you get stuck.\n\n',`SIGNATURE`='Team SourceLead\nWelcome aboard, great to have you!\n{{inviteClient.facebookLink}}\t{{inviteClient.linkedInLink}}\t{{inviteClient.twitterLink}}\t{{inviteClient.googleLink}}' WHERE `UNIQUE_SCENARIO_NAME`='Accept Client Invitation' and `ENTITY_TYPE`='Email';

