UPDATE `EMAIL_SCENARIO` SET `BODY`= 'Dear {{ReferRequirement.professinalName}}\n\n I would like you to review the following Job\nJob ID and Title:{{ReferRequirement.requirementTitle}}\nJob Description:{{ReferRequirement.jobDescription}}\nJob Location:{{ReferRequirement.jobLocation}}\nFor more details please click here {{ReferRequirement.registerLink}}\n\nSourceLead is a leading Global Talent harvesting application can help you grow professionaly and also earn by referring your friends and family to the eligible jobs.\nFor more information please find the FAQ\nif you would like to register please click here {{ReferRequirement.professionalReg}}\nNeed Support?\nWe have video tutorials , live chat, and a great support site to help if you get stuck.\n\n ', `SUBJECT`='{{ReferRequirement.referedProfessionalFirstName}} refered you to the job {{ReferRequirement.requirementTitle}}',`SIGNATURE`='Team SourceLead\nWelcome aboard, great to have you!\n{{RecruiterInvitation.facebookLink}}\t{{RecruiterInvitation.linkedInLink}}\t{{RecruiterInvitation.twitterLink}}\t{{RecruiterInvitation.googleLink}}' WHERE `UNIQUE_SCENARIO_NAME`='Refer Requirment To Professional' and `ENTITY_TYPE`='Email';

